mapper.delete:
delete from declared_yield_field_commodity_berries dyfcb
where dyfcb.field_id = #{fieldId}
  and dyfcb.crop_year = #{cropYear}

mapper.select:
select count(t.declared_yield_field_commodity_berries_guid)
from declared_yield_field_commodity_berries t
where t.field_id = #{fieldId}
and t.crop_year = #{cropYear}
and (COALESCE(t.total_production, 0) > 0 or COALESCE(t.total_production_override, 0) > 0)
